#!/usr/bin/env Rscript
if(!requireNamespace("ape",quietly=TRUE)||!requireNamespace("pkgload",quietly=TRUE))stop("needs ape/pkgload")
mode<-commandArgs(trailingOnly=TRUE);if(!length(mode))mode<-"--preflight";if(!mode%in%c("--preflight","--local"))stop("use --preflight or --local")
src<-"/Users/z3437171/Dropbox/Github Local/eco-climatic-rules/data";out<-"docs/dev-log/evidence/ou-v1-r6";dir.create(out,recursive=TRUE,showWarnings=FALSE);pkgload::load_all(".",compile=TRUE,quiet=TRUE)
av<-read.csv(file.path(src,"Avonet","ELEData","TraitData","AVONET3_BirdTree.csv"));pl<-read.csv(file.path(src,"Delhey_etal_2019","species.level.data.csv"));av$Phylo<-gsub(" ","_",av$Phylo);av<-av[av$Order3=="Passeriformes",];dat<-merge(pl,av,by.x="TipLabel",by.y="Phylo");dat$c_body_mass_g<-as.numeric(scale(log(dat$Mass),scale=FALSE));dat$temp_z<-as.numeric(scale(dat$annual_mean_temperature));dat$precip_z<-as.numeric(scale(dat$annual_precipitation));dat<-dat[complete.cases(dat[,c("TipLabel","c_body_mass_g","temp_z","precip_z")]),]
tree<-ape::read.tree(file.path(src,"Stage2_Hackett_MCC_no_neg.tre"));tree<-ape::drop.tip(tree,setdiff(tree$tip.label,dat$TipLabel));dat<-dat[match(tree$tip.label,dat$TipLabel),];el<-tree$edge.length;eps<-median(el[el>0],na.rm=TRUE)*1e-8;el[is.na(el)|el<=0]<-eps;tree$edge.length<-el;if(!ape::is.binary.tree(tree)){set.seed(42);tree<-ape::multi2di(tree,random=TRUE);el<-tree$edge.length;el[is.na(el)|el<=0]<-median(el[el>0],na.rm=TRUE)*1e-8;tree$edge.length<-el};stopifnot(identical(tree$tip.label,dat$TipLabel),all(tree$edge.length>0))
fit_one<-function(alpha=NULL){tr<-tree;f<-if(is.null(alpha))bf(c_body_mass_g~precip_z+I(precip_z^2)+temp_z+I(temp_z^2)+phylo(1|TipLabel,tree=tr),sigma~temp_z+precip_z) else bf(c_body_mass_g~precip_z+I(precip_z^2)+temp_z+I(temp_z^2)+phylo(1|TipLabel,tree=tr,model="ou"),sigma~temp_z+precip_z);ctl<-drmTMB:::drm_parse_control(drm_control(optimizer=list(eval.max=2000,iter.max=2000)));z<-drmTMB:::drm_build_gaussian_ls_spec(f,dat,env=environment(),weights=NULL,control=ctl,impute=NULL,missing=drmTMB:::drm_parse_missing_control(miss_control()));if(!is.null(alpha)){z$map$log_decay_phylo<-factor(NA);z$start$log_decay_phylo<-log(alpha)};w<-character();t0<-proc.time()[["elapsed"]];fit<-tryCatch(withCallingHandlers(drmTMB:::drm_fit_spec(z,f,gaussian(),ctl,REML=FALSE,penalty=NULL,estimator="ml"),warning=function(e){w<<-c(w,conditionMessage(e));invokeRestart("muffleWarning")}),error=identity);common<-data.frame(model=if(is.null(alpha))"bm"else"ou_fixed",alpha_assumed=if(is.null(alpha))NA_real_ else alpha,elapsed_seconds=proc.time()[["elapsed"]]-t0,warnings=paste(w,collapse=" | "));if(inherits(fit,"error"))return(cbind(common,status="ERROR",objective=NA,AIC=NA,convergence=NA,pdHess=NA,error=conditionMessage(fit)));cbind(common,status="FIT",objective=fit$opt$objective,AIC=stats::AIC(fit),convergence=fit$opt$convergence,pdHess=isTRUE(fit$sdr$pdHess),error=NA_character_)}
grid_normalized<-c(.1,.3,.7,1.3,2.5);depth_scale<-median(ape::node.depth.edgelength(tree)[seq_along(tree$tip.label)]);grid<-grid_normalized/depth_scale;ans<-if(mode=="--preflight")fit_one()else do.call(rbind,c(list(fit_one()),lapply(grid,fit_one)));if(mode!="--preflight"){ans$alpha_normalized<-c(NA_real_,grid_normalized);ans$tree_depth_scale<-depth_scale};utils::write.csv(ans,file.path(out,if(mode=="--preflight")"preflight.csv"else"sensitivity.csv"),row.names=FALSE);if(mode=="--preflight")cat("OU_V1_R6_PREFLIGHT_PASS\n")else cat("OU_V1_R6_PASS\n")
